assert len(AREAS) == 55, len(AREAS)
assert len(PRODUCTOS) == 20, len(PRODUCTOS)
for area, publico, topics in AREAS:
    items = topics.split('|')
    assert len(items) == 20, (area, len(items))
    assert len(set(items)) == 20, area


def normalize(value):
    s = value.casefold().strip()
    return re.sub(r'\s+', ' ', s)


def generate():
    # Iteracion por producto, area y tema + permutacion de orden determinista:
    # evita bloques consecutivos de 20 ideas basadas en un mismo tema.
    rows = []
    for area, publico, topics in AREAS:
        for tema in topics.split('|'):
            for nombre, tipo, proposito, funciones, resultado in PRODUCTOS:
                titulo = f'{nombre}: {tema} ({area})'
                problema = (
                    f'En {tema}, {publico.lower()} necesitan una forma concreta de '
                    f'{proposito} sin depender de conocimientos de programacion.'
                )
                descripcion = (
                    f'Aplicacion completa centrada en {tema}: {proposito}. '
                    f'Incluye {funciones.replace(";", ",")}. '
                    f'Entrega {resultado}.'
                )
                rows.append((area, tema, titulo, publico, problema, descripcion, funciones, resultado, tipo))
    assert len(rows) == 22000
    random.Random(2061029).shuffle(rows)
    titles = [normalize(row[2]) for row in rows]
    assert len(set(titles)) == len(titles)
    identities = [(normalize(row[0]),normalize(row[1]),normalize(row[-1]),normalize(row[2].split(':',1)[0])) for row in rows]
    assert len(set(identities)) == len(identities)

    headers = ['id', 'categoria', 'tema', 'titulo', 'publico', 'problema',
               'descripcion', 'funciones_principales', 'resultado_esperado',
               'tipo_app', 'estado_desarrollo']
    with OUT.open('w', newline='', encoding='utf-8-sig') as f:
        writer=csv.writer(f, delimiter=';', quoting=csv.QUOTE_MINIMAL)
        writer.writerow(headers)
        for i,row in enumerate(rows,1):
            a,t,title,who,problem,desc,fun,outcome,kind=row
            writer.writerow([i,a,t,title,who,problem,desc,fun,outcome,kind,'PENDIENTE'])
    return OUT


def verify():
    with OUT.open('r', newline='',encoding='utf-8-sig') as f:
        reader=csv.DictReader(f,delimiter=';')
        count=0
        names=set()
        areas=Counter()
        types=Counter()
        examples=[]
        for row in reader:
            count+=1
            if count in (1,13,100,750,2000,7500,12500,17500,20000):
                examples.append((count,row['categoria'],row['titulo']))
            title=normalize(row['titulo'])
            if title in names: raise ValueError('Titulo repetido: '+title)
            names.add(title)
            areas[row['categoria']]+=1
            types[row['tipo_app']]+=1
        assert count==22000
        assert len(areas)==55
        assert len(types)>=10
        assert set(areas.values())=={400}
    return {'rows':count, 'categories':len(areas),'types':len(types),
            'size_bytes':OUT.stat().st_size,'examples':examples}

if __name__=='__main__':
    generate()
    print(verify())